corrected_code:
app.post('/webhooks/sendgrid/inbound', multer().none(), async (req, res) => {
  const publicKey = process.env.SENDGRID_WEBHOOK_VERIFICATION_KEY;
  const signature = req.headers['x-twilio-email-event-webhook-signature'];
  const timestamp = req.headers['x-twilio-email-event-webhook-timestamp'];

  const eventWebhook = new EventWebhook();
  const isValid = eventWebhook.verifySignature(publicKey, req.body, signature, timestamp);
  if (!isValid) return res.status(401).send('Signature verification failed');

  const { email, to, subject, text } = req.body;
  const contactId = req.headers['x-crm-contact-id'] || req.body['contact_id'];

  const contact = await db.crmContacts.findOne({ _id: contactId, email: email });
  if (!contact) {
    return res.status(403).json({ error: 'Sender address does not match registered CRM contact email' });
  }

  await db.crmNotes.insertOne({
    contactId: contact._id,
    tenantId: contact.tenantId,
    fromAddress: email,
    recipient: to,
    subject,
    body: text,
    receivedAt: new Date()
  });

  res.status(200).json({ received: true });
});
